import{_ as a,o as t,c as i,a2 as l}from"./chunks/framework.CFuv5BrO.js";const p=JSON.parse('{"title":"项目与对话","description":"项目固定、独立对话、文件夹权限与原地执行的改动清单。","frontmatter":{"title":"项目与对话","description":"项目固定、独立对话、文件夹权限与原地执行的改动清单。","outline":[2]},"headers":[],"relativePath":"design/projects.md","filePath":"design/projects.md","lastUpdated":1795426969000}'),r={name:"design/projects.md"};function o(s,e,d,n,h,c){return t(),i("div",null,[...e[0]||(e[0]=[l('<h1 id="项目与对话" tabindex="-1">项目与对话 <a class="header-anchor" href="#项目与对话" aria-label="Permalink to &quot;项目与对话&quot;">​</a></h1><p>Hearth 的对话分成两类：归属某个固定项目的项目对话，以及不依赖文件夹的独立对话。两者共享同一套任务、审批、记忆和产物链路，区别只在默认工作目录和文件权限。</p><h2 id="项目" tabindex="-1">项目 <a class="header-anchor" href="#项目" aria-label="Permalink to &quot;项目&quot;">​</a></h2><ul><li>项目 = 名称 + 一个本地文件夹，不要求是 Git 仓库。</li><li>Git 仓库根目录：自动记录默认分支，任务在独立 <code>hearth/&lt;task-id&gt;</code> Worktree 中执行，改动可以回滚。</li><li>普通文件夹：任务直接在该目录执行，结束后生成一份“新增 / 修改 / 删除”清单写入会话消息。</li><li>删除项目不会删除对话：相关对话自动转为独立对话，历史保留。</li><li>项目路径、分支和可用性每次读取时实时检查。</li></ul><h2 id="项目对话" tabindex="-1">项目对话 <a class="header-anchor" href="#项目对话" aria-label="Permalink to &quot;项目对话&quot;">​</a></h2><ul><li>创建对话时选择项目，之后不可更改，避免上下文和权限中途变化。</li><li>侧边栏按“项目 / 最近”分组；项目标题左侧可以直接新建对话。</li><li>新对话页显示项目名，并提示在该项目中构建什么。</li><li>任务自动使用项目路径，不需要每次手动选择工作目录。</li></ul><h2 id="独立对话" tabindex="-1">独立对话 <a class="header-anchor" href="#独立对话" aria-label="Permalink to &quot;独立对话&quot;">​</a></h2><ul><li>默认没有文件访问权限，适合纯问答、写作和通用任务。</li><li>如果消息中出现本机绝对路径（<code>D:\\work\\notes</code> 或 <code>\\\\server\\share</code>），该文件夹会作为本次任务的工作目录，并在审批预览和运行卡中展示。</li><li>消息中的路径必须真实存在；指向文件时自动取其父目录。</li></ul><h2 id="与资料库的关系" tabindex="-1">与资料库的关系 <a class="header-anchor" href="#与资料库的关系" aria-label="Permalink to &quot;与资料库的关系&quot;">​</a></h2><p>项目档案会出现在本地资料库的「项目」分类中，和记忆、任务、来源、技能与本地文件夹共用同一棵树。项目对话、任务和产物不依赖外部服务；日常查看和查找统一使用侧栏的「资料库」。完整边界见<a href="/hearth-os/design/knowledge.html">资料库与检索</a>。</p>',10)])])}const _=a(r,[["render",o]]);export{p as __pageData,_ as default};
